changeSet.sql:
CREATE SCHEMA rpt;
CREATE ROLE IF NOT EXISTS fnbcc01 LOGIN;
CREATE ROLE IF NOT EXISTS fnbcc02 LOGIN;
CREATE ROLE IF NOT EXISTS fnbrf01 LOGIN;
CREATE ROLE IF NOT EXISTS rpt_internal LOGIN;
GRANT USAGE ON SCHEMA rpt TO fnbcc01, fnbcc02, fnbrf01, rpt_internal;
ALTER DEFAULT PRIVILEGES IN SCHEMA rpt GRANT SELECT ON TABLES TO fnbcc01, fnbcc02, fnbrf01, rpt_internal;
ALTER ROLE fnbcc01 SET default_transaction_use_follower_reads = 'on';
ALTER ROLE fnbcc02 SET default_transaction_use_follower_reads = 'on';
ALTER ROLE fnbrf01 SET default_transaction_use_follower_reads = 'on';
ALTER ROLE rpt_internal SET default_transaction_use_follower_reads = 'on';
